"""代码生成模块 - 支持多厂商 LLM"""
import os
import json
import requests
from typing import Dict, Any, Optional
from dataclasses import dataclass
from .task_splitter import SplitTask
from .config import get_config


@dataclass
class GeneratedCode:
    """生成的代码"""
    task_id: str
    file_path: str
    original_content: str
    generated_patch: str
    status: str  # success/failed
    error_message: str = ""


class CodeGenerator:
